use std::env;
use std::process;

fn main() {
    let args: Vec<String> = env::args().collect();

    // Print header
    println!();
    println!("7-Zip (a) 26.00 (x64) : Copyright (c) 1999-2026 Igor Pavlov : 2026-02-12");
    println!(" 64-bit locale=C.UTF-8 Threads:{} OPEN_MAX:1024", num_cpus());

    if args.len() < 2 {
        print_usage();
        process::exit(0);
    }

    let command = &args[1];

    match command.as_str() {
        "--help" | "-h" | "?" => {
            print_usage();
        }
        "a" => handle_add(&args),
        "l" => handle_list(&args),
        "x" => handle_extract_full_paths(&args),
        "e" => handle_extract_no_paths(&args),
        "t" => handle_test(&args),
        "h" => handle_hash(&args),
        "i" => handle_info(&args),
        "d" => handle_delete(&args),
        "rn" => handle_rename(&args),
        "b" => handle_benchmark(&args),
        "u" => handle_update(&args),
        _ => {
            println!();
            println!();
            println!("Command Line Error:");
            println!("Unsupported command:");
            println!("{}", command);
            process::exit(1);
        }
    }
}

fn num_cpus() -> usize {
    // Try to get CPU count from environment or use a default
    if let Ok(count_str) = std::env::var("RAYON_NUM_THREADS") {
        count_str.parse().unwrap_or(1)
    } else {
        // This is a fallback - the original shows 192
        std::thread::available_parallelism()
            .map(|n| n.get())
            .unwrap_or(1)
    }
}

