    println!("  -ao{{a|s|t|u}} : set Overwrite mode");
    println!("  -an : disable archive_name field");
    println!("  -bb[0-3] : set output log level");
    println!("  -bd : disable progress indicator");
    println!("  -bs{{o|e|p}}{{0|1|2}} : set output stream for output/error/progress line");
    println!("  -bt : show execution time statistics");
    println!("  -i[r[-|0]][m[-|2]][w[-]]{{@listfile|!wildcard}} : Include filenames");
