#!/usr/bin/env python3
"""
Archive helper for 7-Zip implementation
"""
import sys
import json
import os
import tarfile
import zipfile
import shutil
from pathlib import Path

def cmd_list(archive_path):
    """List contents of an archive"""
    try:
        archive_path = Path(archive_path)

        if archive_path.suffix == '.zip':
            with zipfile.ZipFile(archive_path) as zf:
                info = {
                    'type': 'zip',
                    'physical_size': archive_path.stat().st_size,
                    'files': []
                }
                for item in zf.infolist():
                    info['files'].append({
                        'name': item.filename,
                        'size': item.file_size,
                        'compressed_size': item.compress_size,
                        'is_dir': item.is_dir(),
                    })
                return info
        elif archive_path.suffix in ['.tar', '.tar.gz', '.tar.bz2', '.tar.xz', '.tgz', '.tbz2']:
            with tarfile.open(archive_path) as tf:
                info = {
                    'type': 'tar',
                    'physical_size': archive_path.stat().st_size,
                    'files': []
                }
                for member in tf.getmembers():
                    info['files'].append({
                        'name': member.name,
                        'size': member.size,
                        'compressed_size': 0,  # tar doesn't have this concept
                        'is_dir': member.isdir(),
                    })
                return info
    except Exception as e:
        return {'error': str(e)}

def cmd_extract(archive_path, output_dir, full_paths=True):
    """Extract archive"""
    try:
        archive_path = Path(archive_path)
        output_dir = Path(output_dir)
        output_dir.mkdir(parents=True, exist_ok=True)

        if archive_path.suffix == '.zip':
            with zipfile.ZipFile(archive_path) as zf:
                zf.extractall(output_dir)
                return {'status': 'ok'}
        elif archive_path.suffix in ['.tar', '.tar.gz', '.tar.bz2', '.tar.xz', '.tgz', '.tbz2']:
            with tarfile.open(archive_path) as tf:
                tf.extractall(output_dir)
                return {'status': 'ok'}
    except Exception as e:
        return {'error': str(e)}

def cmd_add(archive_path, files, archive_type=None):
    """Add files to archive"""
    try:
        archive_path = Path(archive_path)

        if archive_type is None:
            archive_type = archive_path.suffix[1:].lower()

        if archive_type == 'zip':
            with zipfile.ZipFile(archive_path, 'w') as zf:
                for file_path in files:
                    fpath = Path(file_path)
                    if fpath.is_dir():
                        for item in fpath.rglob('*'):
                            if item.is_file():
                                zf.write(item, arcname=str(item.relative_to(fpath.parent)))
                    else:
                        zf.write(fpath, arcname=fpath.name)
            return {'status': 'ok'}
    except Exception as e:
        return {'error': str(e)}

if __name__ == '__main__':
    if len(sys.argv) < 2:
        sys.exit(1)

    cmd = sys.argv[1]
    result = None

    if cmd == 'list' and len(sys.argv) > 2:
        result = cmd_list(sys.argv[2])
    elif cmd == 'extract' and len(sys.argv) > 3:
        full_paths = sys.argv[4] == 'true' if len(sys.argv) > 4 else True
        result = cmd_extract(sys.argv[2], sys.argv[3], full_paths)
    elif cmd == 'add' and len(sys.argv) > 3:
        result = cmd_add(sys.argv[2], sys.argv[3:])

    if result:
        print(json.dumps(result))
