        process::exit(0);
    }

    let command = &args[1];
    let other_args = &args[2..];

    match command.as_str() {
        "--help" | "-h" | "?" => {
            cli::print_usage();
        }
        "a" => {
            if let Err(e) = commands::add::handle(other_args) {
                eprintln!("Error: {}", e);
                process::exit(1);
            }
        },
        "l" => {
            if let Err(e) = commands::list::handle(other_args) {
                eprintln!("Error: {}", e);
                process::exit(1);
            }
        },
        "x" => {
            if let Err(e) = commands::extract::handle(other_args, true) {
                eprintln!("Error: {}", e);
                process::exit(1);
            }
        },
        "e" => {
            if let Err(e) = commands::extract::handle(other_args, false) {
                eprintln!("Error: {}", e);
                process::exit(1);
            }
        },
        "t" => {
            if let Err(e) = commands::test::handle(other_args) {
                eprintln!("Error: {}", e);
                process::exit(1);
            }
        },
        "h" => {
            if let Err(e) = commands::hash::handle(other_args) {
                eprintln!("Error: {}", e);
                process::exit(1);
            }
        },
        "i" => {
            if let Err(e) = commands::info::handle(other_args) {
                eprintln!("Error: {}", e);
                process::exit(1);
            }
        },
        "d" => {
            if let Err(e) = commands::delete::handle(other_args) {
                eprintln!("Error: {}", e);
                process::exit(1);
            }
        },
        "rn" => {
            if let Err(e) = commands::rename::handle(other_args) {
                eprintln!("Error: {}", e);
                process::exit(1);
            }
        },
        "b" => {
            if let Err(e) = commands::benchmark::handle(other_args) {
                eprintln!("Error: {}", e);
                process::exit(1);
            }
        },
        "u" => {
            if let Err(e) = commands::update::handle(other_args) {
                eprintln!("Error: {}", e);
                process::exit(1);
            }
        },
        _ => {
            println!();
            println!();
            println!("Command Line Error:");
            println!("Unsupported command:");
            println!("{}", command);
            process::exit(1);
        }
    }
}

fn get_num_threads() -> usize {
    std::thread::available_parallelism()
        .map(|n| n.get())
        .unwrap_or(1)
}
