    pub fn from_raw_args(raw_args: &[String]) -> Self {
        let mut archive = String::new();
        let mut files = Vec::new();
        let mut switches = HashMap::new();

        let mut i = 0;
        while i < raw_args.len() {
            let arg = &raw_args[i];

            if arg == "--" {
                // Stop parsing switches
                i += 1;
                while i < raw_args.len() {
                    if archive.is_empty() {
                        archive = raw_args[i].clone();
                    } else {
                        files.push(raw_args[i].clone());
                    }
                    i += 1;
                }
                break;
            } else if arg.starts_with('-') && arg.len() > 1 {
                // It's a switch
                parse_switch(arg, &mut switches);
                i += 1;
            } else {
                // It's a positional argument
                if archive.is_empty() {
                    archive = arg.clone();
                } else {
                    files.push(arg.clone());
                }
                i += 1;
            }
        }

        Args { archive, files, switches }
    }
}

fn parse_switch(switch: &str, switches: &mut HashMap<String, String>) {
    if switch == "-y" {
        switches.insert("yes".to_string(), "true".to_string());
    } else if switch == "-bd" {
        switches.insert("no_progress".to_string(), "true".to_string());
    } else if switch.starts_with("-o") {
        let value = switch[2..].to_string();
        switches.insert("output_dir".to_string(), value);
    } else if switch.starts_with("-p") {
        let value = switch[2..].to_string();
        switches.insert("password".to_string(), value);
    } else if switch.starts_with("-m") {
        let value = switch[2..].to_string();
        switches.insert("method".to_string(), value);
    } else if switch.starts_with("-t") {
        let value = switch[2..].to_string();
        switches.insert("type".to_string(), value);
    } else if switch.starts_with("-bb") {
        if switch.len() > 3 {
            switches.insert("log_level".to_string(), switch[3..].to_string());
        }
    } else if switch == "-slt" {
        switches.insert("slt".to_string(), "true".to_string());
    }
}
