    return result

def cmd_add(archive_path, files_to_add, archive_type=None):
    """Add files to archive"""
    archive_path = Path(archive_path)

    if archive_type is None:
        archive_type = get_archive_type(str(archive_path))

    result = {
        'type': 'add',
        'archive': str(archive_path),
        'archive_type': archive_type,
        'files_added': 0,
        'total_size': 0,
    }

    try:
        if archive_type == 'zip' or archive_path.suffix.lower() == '.zip':
            mode = 'a' if archive_path.exists() else 'w'
            with zipfile.ZipFile(archive_path, mode) as zf:
                for file_spec in files_to_add:
                    file_path = Path(file_spec)
                    if file_path.is_dir():
                        for item in file_path.rglob('*'):
                            if item.is_file():
                                arcname = str(item.relative_to(file_path.parent))
                                zf.write(item, arcname=arcname)
                                result['files_added'] += 1
                                result['total_size'] += item.stat().st_size
                    elif file_path.is_file():
                        arcname = file_path.name
                        zf.write(file_path, arcname=arcname)
                        result['files_added'] += 1
                        result['total_size'] += file_path.stat().st_size

            result['archive_size'] = archive_path.stat().st_size
        else:
            result['error'] = f"Archive type {archive_type} not yet supported for add"
    except Exception as e:
        result['error'] = str(e)

    return result

def cmd_test(archive_path):
    """Test archive integrity"""
    archive_path = Path(archive_path)
    archive_type = get_archive_type(str(archive_path))

    result = {
        'type': 'test',
        'archive': str(archive_path),
        'archive_type': archive_type,
        'status': 'ok',
    }

    try:
        if archive_type == 'zip':
            with zipfile.ZipFile(archive_path) as zf:
                bad = zf.testzip()
                if bad:
                    result['status'] = 'error'
                    result['bad_file'] = bad
        elif archive_type in ['tar', 'gzip', 'bzip2', 'xz']:
            with tarfile.open(archive_path) as tf:
                tf.getmembers()
    except Exception as e:
        result['status'] = 'error'
        result['error'] = str(e)

    return result

def cmd_hash(files):
    """Calculate hash values for files"""
    result = {
        'type': 'hash',
        'files': [],
        'hashes': {},
    }

    for file_path_str in files:
        file_path = Path(file_path_str)
        if not file_path.exists():
            continue

        # Calculate CRC32
        crc32 = 0
        try:
            with open(file_path, 'rb') as f:
                while chunk := f.read(8192):
                    for byte in chunk:
                        crc32 = (crc32 ^ byte) * 0x04C11DB7
                        crc32 &= 0xFFFFFFFF
                        for _ in range(8):
                            crc32 = ((crc32 << 1) ^ (0x04C11DB7 if crc32 & 0x80000000 else 0)) & 0xFFFFFFFF
        except:
            pass

        result['files'].append({
            'path': file_path_str,
            'size': file_path.stat().st_size if file_path.is_file() else 0,
            'crc32': f"{crc32:08X}",
        })

    return result

def cmd_info():
