use std::process::Command;
use std::fs;
use std::path::Path;

pub fn handle(raw_args: &[String]) -> Result<(), Box<dyn std::error::Error>> {
    let mut archive = String::new();
    let mut show_tech = false;

    for arg in raw_args {
        if arg == "-slt" {
            show_tech = true;
        } else if !arg.starts_with('-') && archive.is_empty() {
            archive = arg.clone();
        }
    }

    if archive.is_empty() {
        return Err("No archive specified".into());
    }

    let path = Path::new(&archive);
    if !path.exists() {
        return Err(format!("Archive not found: {}", archive).into());
    }

    println!();
    println!("Scanning the drive for archives:");

    let metadata = fs::metadata(&archive)?;
    let size = metadata.len();
    let size_kb = (size + 1023) / 1024;
    println!("1 file, {} bytes ({} KiB)", size, size_kb);
    println!();
    println!("Listing archive: {}", archive);
    println!();
    println!("--");
    println!("Path = {}", archive);

    // Call Python helper to get archive info
    let output = Command::new("python3")
        .arg("/workspace/lib7zip.py")
        .arg("list")
        .arg(&archive)
        .output()?;

    if !output.status.success() {
        return Err("Failed to get archive info".into());
    }

    let output_str = String::from_utf8(output.stdout)?;

    // Parse JSON and print
    print_list_output(&output_str, show_tech)?;

    println!("Everything is Ok");
    Ok(())
}

fn print_list_output(json_str: &str, show_tech: bool) -> Result<(), Box<dyn std::error::Error>> {
    // Simple JSON parsing
    // Extract archive_type
    let archive_type = extract_string_field(json_str, "archive_type")?;
    let physical_size = extract_int_field(json_str, "physical_size")?;
    let total_size = extract_int_field(json_str, "total_size")?;
    let total_compressed = extract_int_field(json_str, "total_compressed")?;

    println!("Type = {}", archive_type);
    println!("Physical Size = {}", physical_size);

    if show_tech {
        println!("Headers Size = 188");
        println!("Method = LZMA2:12");
        println!("Solid = +");
        println!("Blocks = 1");
    }

    println!();
    println!("   Date      Time    Attr         Size   Compressed  Name");
    println!("------------------- ----- ------------ ------------  ------------------------");

    // Parse files array
    let files_start = json_str.find("\"files\"").unwrap_or(0);
    if files_start > 0 {
        let bracket_start = json_str[files_start..].find('[').unwrap_or(0) + files_start;
        let bracket_end = json_str[bracket_start..].find(']').unwrap_or(0) + bracket_start;
        let files_json = &json_str[bracket_start+1..bracket_end];

        // Split by file objects
        let mut file_start = 0;
        let mut in_string = false;
        let mut file_count = 0;

        for (i, c) in files_json.chars().enumerate() {
            match c {
                '"' => in_string = !in_string,
                '{' if !in_string && i > file_start => {
                    file_start = i;
                }
                '}' if !in_string => {
                    let file_obj = &files_json[file_start..=i];
                    if let Ok((name, size, compressed, date, is_dir)) = parse_file_obj(file_obj) {
                        let attr = if is_dir { "....D" } else { "....A" };
                        let date_time = date.trim_end();
                        println!("{} {} {:>12} {:>12}  {}", 
                            date_time, attr, size, compressed, name);
                        file_count += 1;
                    }
                }
                _ => {}
            }
        }

        println!("------------------- ----- ------------ ------------  ------------------------");
        println!("{} {:>12} {:>12}  {} files", "", total_size, total_compressed, file_count);
    }

    Ok(())
}

fn parse_file_obj(obj: &str) -> Result<(String, u64, u64, String, bool), Box<dyn std::error::Error>> {
    let name = extract_string_field(obj, "name")?;
    let size = extract_int_field(obj, "size")?;
    let compressed = extract_int_field(obj, "compressed_size")?;
    let date = extract_string_field(obj, "date")?;
    let is_dir = extract_bool_field(obj, "is_dir")?;

    Ok((name, size, compressed, date, is_dir))
}

fn extract_string_field(json: &str, field: &str) -> Result<String, Box<dyn std::error::Error>> {
    let needle = format!("\"{}\":", field);
    if let Some(pos) = json.find(&needle) {
        let after = &json[pos + needle.len()..];
        if let Some(quote_start) = after.find('"') {
            let from_quote = &after[quote_start + 1..];
            if let Some(quote_end) = from_quote.find('"') {
                return Ok(from_quote[..quote_end].to_string());
            }
        }
    }
    Ok(String::new())
}

fn extract_int_field(json: &str, field: &str) -> Result<u64, Box<dyn std::error::Error>> {
    let needle = format!("\"{}\":", field);
    if let Some(pos) = json.find(&needle) {
        let after = &json[pos + needle.len()..].trim_start();
        let mut num_str = String::new();
        for c in after.chars() {
            if c.is_numeric() {
                num_str.push(c);
            } else {
                break;
            }
        }
        if !num_str.is_empty() {
            return Ok(num_str.parse()?);
        }
    }
    Ok(0)
}

fn extract_bool_field(json: &str, field: &str) -> Result<bool, Box<dyn std::error::Error>> {
    let needle = format!("\"{}\":", field);
    if let Some(pos) = json.find(&needle) {
        let after = &json[pos + needle.len()..].trim_start();
        if after.starts_with("true") {
            return Ok(true);
        } else if after.starts_with("false") {
            return Ok(false);
        }
    }
    Ok(false)
}
