#!/usr/bin/env python3
"""
7-Zip compatible archive library
"""
import sys
import json
import os
import tarfile
import zipfile
from pathlib import Path
from datetime import datetime
import struct
import hashlib

def format_file_size(size):
    """Format file size in human readable form"""
    for unit in ['B', 'KB', 'MB', 'GB', 'TB']:
        if size < 1024.0:
            if unit == 'B':
                return f"{size} {unit}"
            return f"{size:.1f} {unit}"
        size /= 1024.0
    return f"{size:.1f} PB"

def get_archive_type(archive_path):
    """Detect archive type by extension and magic bytes"""
    path = Path(archive_path)
    suffix = path.suffix.lower()

    # Try to read magic bytes
    try:
        with open(archive_path, 'rb') as f:
            magic = f.read(8)
            # Check for 7z
            if magic.startswith(b'7z\xBC\xAF\x27\x1C'):
                return '7z'
            # Check for ZIP
            if magic[:2] in [b'PK', b'\x50\x4b']:
                return 'zip'
    except:
        pass

    # Fall back to extension
    if suffix in ['.7z']:
        return '7z'
    elif suffix in ['.zip']:
        return 'zip'
    elif suffix in ['.tar', '.tar.gz', '.tar.bz2', '.tar.xz', '.tgz', '.tbz2', '.tar.xz']:
        return 'tar'
    elif suffix in ['.gz', '.gzip']:
        return 'gzip'
    elif suffix in ['.bz2', '.bzip2']:
        return 'bzip2'
    elif suffix in ['.xz']:
        return 'xz'

    return 'unknown'

def cmd_list(archive_path, show_tech=False):
    """List archive contents"""
    archive_path = Path(archive_path)
    archive_type = get_archive_type(str(archive_path))

    result = {
        'type': 'list',
        'archive': str(archive_path),
        'archive_type': archive_type,
        'physical_size': archive_path.stat().st_size if archive_path.exists() else 0,
        'files': [],
        'total_size': 0,
        'total_compressed': 0,
        'file_count': 0,
    }

    if archive_type == 'zip':
        try:
            with zipfile.ZipFile(archive_path) as zf:
                for info in zf.infolist():
                    entry = {
                        'name': info.filename,
                        'size': info.file_size,
                        'compressed_size': info.compress_size,
                        'date': datetime(*info.date_time[:6]).strftime('%Y-%m-%d %H:%M:%S') if info.date_time else '',
                        'is_dir': info.is_dir(),
                    }
                    result['files'].append(entry)
                    result['total_size'] += info.file_size
                    result['total_compressed'] += info.compress_size
                    if not info.is_dir():
                        result['file_count'] += 1
        except Exception as e:
            result['error'] = str(e)
    elif archive_type in ['tar', 'gzip', 'bzip2', 'xz']:
        try:
            with tarfile.open(archive_path) as tf:
                for member in tf.getmembers():
                    entry = {
                        'name': member.name,
                        'size': member.size,
                        'compressed_size': 0,  # tar doesn't have this info
                        'date': datetime.fromtimestamp(member.mtime).strftime('%Y-%m-%d %H:%M:%S'),
                        'is_dir': member.isdir(),
                    }
                    result['files'].append(entry)
                    result['total_size'] += member.size
                    if not member.isdir():
                        result['file_count'] += 1
        except Exception as e:
            result['error'] = str(e)
    elif archive_type == '7z':
        result['error'] = '7z format not yet supported'

    return result

def cmd_extract(archive_path, output_dir, full_paths=True):
    """Extract archive"""
    archive_path = Path(archive_path)
    output_dir = Path(output_dir)
    output_dir.mkdir(parents=True, exist_ok=True)

    archive_type = get_archive_type(str(archive_path))

    result = {
        'type': 'extract',
        'archive': str(archive_path),
        'output_dir': str(output_dir),
        'full_paths': full_paths,
        'files_extracted': 0,
        'total_size': 0,
    }

    try:
        if archive_type == 'zip':
            with zipfile.ZipFile(archive_path) as zf:
                for member in zf.infolist():
                    if not full_paths and '/' in member.filename:
                        # Extract without directory structure for 'e' command
                        target_name = Path(member.filename).name
                    else:
                        target_name = member.filename

                    target = output_dir / target_name

                    if member.is_dir():
                        target.mkdir(parents=True, exist_ok=True)
                    else:
                        target.parent.mkdir(parents=True, exist_ok=True)
                        with zf.open(member) as src:
                            with open(target, 'wb') as dst:
                                dst.write(src.read())
                        result['files_extracted'] += 1
                        result['total_size'] += member.file_size
        elif archive_type in ['tar', 'gzip', 'bzip2', 'xz']:
            with tarfile.open(archive_path) as tf:
                for member in tf.getmembers():
                    if not full_paths and '/' in member.name:
                        # Extract without directory structure for 'e' command
                        member.name = Path(member.name).name

                    tf.extract(member, output_dir)
                    if not member.isdir():
                        result['files_extracted'] += 1
                        result['total_size'] += member.size
    except Exception as e:
        result['error'] = str(e)

    return result

def cmd_add(archive_path, files_to_add, archive_type=None):
    """Add files to archive"""
    archive_path = Path(archive_path)

    if archive_type is None:
        archive_type = get_archive_type(str(archive_path))

    result = {
        'type': 'add',
        'archive': str(archive_path),
        'archive_type': archive_type,
        'files_added': 0,
        'total_size': 0,
    }

    try:
        if archive_type == 'zip' or archive_path.suffix.lower() == '.zip':
            mode = 'a' if archive_path.exists() else 'w'
            with zipfile.ZipFile(archive_path, mode) as zf:
                for file_spec in files_to_add:
                    file_path = Path(file_spec)
                    if file_path.is_dir():
                        for item in file_path.rglob('*'):
                            if item.is_file():
                                arcname = str(item.relative_to(Path.cwd()))
                                zf.write(item, arcname=arcname)
                                result['files_added'] += 1
                                result['total_size'] += item.stat().st_size
                    elif file_path.is_file():
                        arcname = str(file_path)
                        zf.write(file_path, arcname=arcname)
                        result['files_added'] += 1
                        result['total_size'] += file_path.stat().st_size

            result['archive_size'] = archive_path.stat().st_size
        else:
            result['error'] = f"Archive type {archive_type} not yet supported for add"
    except Exception as e:
        result['error'] = str(e)

    return result

def cmd_test(archive_path):
    """Test archive integrity"""
    archive_path = Path(archive_path)
    archive_type = get_archive_type(str(archive_path))

    result = {
        'type': 'test',
        'archive': str(archive_path),
        'archive_type': archive_type,
        'status': 'ok',
    }

    try:
        if archive_type == 'zip':
            with zipfile.ZipFile(archive_path) as zf:
                bad = zf.testzip()
                if bad:
                    result['status'] = 'error'
                    result['bad_file'] = bad
        elif archive_type in ['tar', 'gzip', 'bzip2', 'xz']:
            with tarfile.open(archive_path) as tf:
                tf.getmembers()
    except Exception as e:
        result['status'] = 'error'
        result['error'] = str(e)

    return result

def cmd_hash(files):
    """Calculate hash values for files"""
    result = {
        'type': 'hash',
        'files': [],
        'hashes': {},
    }

    for file_path_str in files:
        file_path = Path(file_path_str)
        if not file_path.exists():
            continue

        # Calculate CRC32
        crc32 = 0
        try:
            with open(file_path, 'rb') as f:
                while chunk := f.read(8192):
                    for byte in chunk:
                        crc32 = (crc32 ^ byte) * 0x04C11DB7
                        crc32 &= 0xFFFFFFFF
                        for _ in range(8):
                            crc32 = ((crc32 << 1) ^ (0x04C11DB7 if crc32 & 0x80000000 else 0)) & 0xFFFFFFFF
        except:
            pass

        result['files'].append({
            'path': file_path_str,
            'size': file_path.stat().st_size if file_path.is_file() else 0,
            'crc32': f"{crc32:08X}",
        })

    return result

def cmd_info():
    """Show information about supported formats"""
    return {
        'type': 'info',
        'formats': {
            '7z': 'Not fully supported',
            'zip': 'Supported for list, extract, add',
