pub fn handle(raw_args: &[String]) -> Result<(), Box<dyn std::error::Error>> {
    let files: Vec<&String> = raw_args.iter().filter(|a| !a.starts_with('-')).collect();

    if files.is_empty() {
        return Err("No files specified".into());
    }

    println!();
    println!("Scanning");

    // Count total size
    let mut total_size = 0;
    let mut file_count = 0;
    for file in &files {
        let path = Path::new(file);
        if path.exists() && path.is_file() {
            if let Ok(metadata) = fs::metadata(file) {
                total_size += metadata.len();
                file_count += 1;
            }
        }
    }

    let size_kb = (total_size + 1023) / 1024;
    println!("{} file, {} bytes ({} KiB)", file_count, total_size, size_kb);
    println!();
    println!("CRC32             Size  Name");
    println!("--------  -------------  ------------");

    let mut combined_crc32 = 0u32;

