use std::path::Path;
use std::fs;
use std::io::Read;

pub fn handle(raw_args: &[String]) -> Result<(), Box<dyn std::error::Error>> {
    let files: Vec<&String> = raw_args.iter().filter(|a| !a.starts_with('-')).collect();

    if files.is_empty() {
        return Err("No files specified".into());
    }

    println!();
    println!("Scanning");

    // Count total size
    let mut total_size = 0;
    let mut file_count = 0;
    for file in &files {
        let path = Path::new(file);
        if path.exists() && path.is_file() {
            if let Ok(metadata) = fs::metadata(file) {
                total_size += metadata.len();
                file_count += 1;
            }
        }
    }

    let size_kb = (total_size + 1023) / 1024;
    println!("{} file, {} bytes ({} KiB)", file_count, total_size, size_kb);
    println!();
    println!("CRC32             Size  Name");
    println!("--------  -------------  ------------");

    let mut combined_crc32 = 0u32;

    for file in files {
        let path = Path::new(file);
        if path.exists() && path.is_file() {
            if let Ok(metadata) = fs::metadata(file) {
                let crc32 = calculate_crc32(file)?;
                println!("{:08X}  {:>12}  {}", crc32, metadata.len(), file);
                combined_crc32 = crc32;
            }
        }
    }

    println!("--------  -------------  ------------");
    println!("{:08X}  {:>12} ", combined_crc32, total_size);
    println!();
    println!("Size: {}", total_size);
    println!();
    println!("CRC32  for data:              {:08X}", combined_crc32);
    println!();
    println!("Everything is Ok");

    Ok(())
}

fn calculate_crc32(file: &str) -> Result<u32, Box<dyn std::error::Error>> {
    let mut f = fs::File::open(file)?;
    let mut buf = [0u8; 8192];
    let mut crc32 = 0xFFFFFFFFu32;

    loop {
        let n = f.read(&mut buf)?;
        if n == 0 { break; }

        for byte in &buf[..n] {
            let idx = ((crc32 ^ (*byte as u32)) & 0xFF) as usize;
            crc32 = ((crc32 >> 8) ^ CRC32_TABLE[idx]) & 0xFFFFFFFF;
        }
    }

    Ok(crc32 ^ 0xFFFFFFFF)
}

